@RestController
@RequestMapping("FlightAPI")
public class FlightAPI {

    @Autowired
    private FlightService flightService;

    @GetMapping(value = "/{source}/{destination}/{journeyDate}", headers = "Accept=application/json")
    public List<SearchFlights> searchFlights(@PathVariable String source, @PathVariable String destination,
            @PathVariable String journeyDate) throws Exception {
        Calendar jDate = CalendarUtility.getCalendarFromString(journeyDate);
        return flightService.getFlights(source, destination, jDate);
    }

    @RequestMapping(value = "/source", method = RequestMethod.GET, headers = "Accept=application/json")
    public List<String> getSources() throws Exception {
        return flightService.getSources();
    }

    @RequestMapping(value = "/destination", method = RequestMethod.GET, headers = "Accept=application/json")
    public ResponseEntity<List<String>> getDestinations() throws Exception {
        return new ResponseEntity<>(flightService.getDestinations(), HttpStatus.OK);
    }
}

@Controller
public class FlightController {

    @Autowired
    private Environment environment;
    private final RestTemplate restTemplate;

    public FlightController(RestTemplateBuilder builder) {
        this.restTemplate = builder.build();
    }

    @PostMapping(value = "/searchFlights")
    public ModelAndView flightSearch(@Valid @ModelAttribute("command") SearchFlights searchFlights,
            BindingResult result, ModelMap model) {

        if (result.hasErrors()) return new ModelAndView("searchFlights", "command", searchFlights);

        String restUrl = environment.getProperty("RestUrl");

        List<SearchFlights> flights = restTemplate.getForObject(
            restUrl + "/FlightAPI/" + searchFlights.getSource() + "/" +
            searchFlights.getDestination() + "/" + searchFlights.getJourneyDate(),
            List.class
        );

        List<String> sources = restTemplate.getForObject(restUrl + "/FlightAPI/source", List.class);
        List<String> destinations = restTemplate.getForObject(restUrl + "/FlightAPI/destination", List.class);

        model.addAttribute("availableFlights", flights);
        model.addAttribute("size", flights.size());

        ModelAndView view = new ModelAndView("searchFlights", "command", searchFlights);
        view.addObject("sourceList", sources);
        view.addObject("destinationList", destinations);
        return view;
    }
}

@Controller
@SessionAttributes("contextPath")
@PropertySource("classpath:configuration.properties")
public class HomeController {

    @Autowired
    private Environment environment;
    private final RestTemplate restTemplate;

    public HomeController(RestTemplateBuilder builder) {
        this.restTemplate = builder.build();
    }

    @GetMapping(value = "/flight")
    public ModelAndView getSourceDestinationDetails(HttpSession session, HttpServletRequest request,
            SessionStatus status) {
        String restUrl = environment.getProperty("RestUrl");
        session.setAttribute("contextPath", request.getContextPath());
        status.setComplete();

        List<String> sources = restTemplate.getForObject(restUrl + "/FlightAPI/source", List.class);
        List<String> destinations = restTemplate.getForObject(restUrl + "/FlightAPI/destination", List.class);

        ModelAndView mv = new ModelAndView("searchFlights", "command", new SearchFlights());
        mv.addObject("sourceList", sources);
        mv.addObject("destinationList", destinations);
        return mv;
    }
}

